window.J277_TOPICS={"1.3":"Computer networks, connections and protocols","1.4":"Network security","1.5":"Systems software","1.6":"Ethical, legal, cultural and environmental impacts","2.1":"Algorithms","2.2":"Programming fundamentals","2.3.1":"Defensive design","2.3.2":"Testing","2.4":"Boolean logic"};
window.J277_BANK=[{"id":"1-3-01","topic":"1.3","type":"mcq","difficulty":"core","question":"What does WAN stand for?","options":["Wide Area Network","Wireless Access Network","Web Application Network","Wired Access Node"],"answer":0,"explanation":"A WAN connects devices over a large geographical area.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-02","topic":"1.3","type":"mcq","difficulty":"core","question":"What is network bandwidth?","options":["The maximum rate of data transfer over a connection","The time taken for one packet to arrive","The number of devices with an IP address","The physical length of a cable"],"answer":0,"explanation":"Bandwidth describes how much data can be transmitted per unit time.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-03","topic":"1.3","type":"mcq","difficulty":"core","question":"What does Mbps measure?","options":["Megabits per second","Megabytes per session","Milliseconds per second","Millions of packets stored"],"answer":0,"explanation":"Mbps is a rate in millions of bits per second.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-04","topic":"1.3","type":"multi","difficulty":"core","question":"Which are genuine benefits of networking computers?","options":["Sharing files and folders","Sharing a printer","Sharing an internet connection","Automatically preventing every security attack"],"answer":[0,1,2],"explanation":"A network supports resource sharing but needs security measures.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-05","topic":"1.3","type":"mcq","difficulty":"core","question":"What is the main purpose of a router?","options":["Forward packets between different networks","Store user documents","Convert images to binary","Run anti-virus scans"],"answer":0,"explanation":"A router chooses a route to forward packets between networks.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-06","topic":"1.3","type":"mcq","difficulty":"core","question":"What does DNS stand for?","options":["Domain Name System","Data Network Storage","Digital Node Service","Dynamic Network Security"],"answer":0,"explanation":"DNS resolves domain names to IP addresses.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-07","topic":"1.3","type":"mcq","difficulty":"core","question":"What is a LAN?","options":["A network covering a small local area","A network always crossing national borders","A connection that uses only satellites","A network that cannot use Wi-Fi"],"answer":0,"explanation":"A LAN generally covers a home, office or school site.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-08","topic":"1.3","type":"mcq","difficulty":"secure","question":"What does a client do in a client-server network?","options":["Requests services or resources from a server","Controls every network administrator account","Always routes internet packets","Provides all network storage to other clients"],"answer":0,"explanation":"Clients request resources; servers provide centralised services.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-09","topic":"1.3","type":"mcq","difficulty":"secure","question":"Why might a small office choose a peer-to-peer network?","options":["It may be inexpensive and simple without a dedicated server","It guarantees centralised backups","It gives every user identical permissions automatically","It prevents all malware infections"],"answer":0,"explanation":"Peer-to-peer networks can suit small groups but are harder to manage centrally.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-10","topic":"1.3","type":"mcq","difficulty":"core","question":"What is a network protocol?","options":["A set of agreed rules for communication","A physical type of cable","A computer's screen resolution","A file compression algorithm only"],"answer":0,"explanation":"Protocols define how devices format and exchange data.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-11","topic":"1.3","type":"mcq","difficulty":"secure","question":"Which service commonly converts an easy-to-remember website name to an IP address?","options":["DNS","POP3","FTP","SMTP"],"answer":0,"explanation":"DNS supports name resolution so browsers can contact hosts.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-12","topic":"1.3","type":"mcq","difficulty":"secure","question":"Which protocol is most associated with sending email between mail servers?","options":["SMTP","POP3","FTP","HTTP"],"answer":0,"explanation":"SMTP transfers outgoing messages; POP3 is used to retrieve email.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-13","topic":"1.3","type":"mcq","difficulty":"secure","question":"What is the main role of POP3?","options":["Retrieving emails from a mail server","Sending web pages to a browser","Finding IP addresses from domain names","Encrypting every file on a computer"],"answer":0,"explanation":"POP3 is an email retrieval protocol.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-14","topic":"1.3","type":"mcq","difficulty":"secure","question":"What is the main purpose of FTP?","options":["Transferring files over a network","Translating domain names","Delivering secure voice calls","Detecting malicious files"],"answer":0,"explanation":"FTP stands for File Transfer Protocol.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-15","topic":"1.3","type":"mcq","difficulty":"secure","question":"Why does HTTPS provide more protection than ordinary HTTP?","options":["It uses encryption to protect data in transit","It removes the need for a server","It blocks every malicious download","It makes bandwidth unlimited"],"answer":0,"explanation":"HTTPS protects communication with TLS encryption.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-16","topic":"1.3","type":"mcq","difficulty":"secure","question":"What is packet switching?","options":["Splitting data into packets that can take routes across a network","Sending all data along one permanently reserved circuit","Storing every message permanently on a router","Turning binary numbers into hexadecimal"],"answer":0,"explanation":"Packets include addressing information and are reassembled at their destination.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-17","topic":"1.3","type":"tf","difficulty":"core","question":"A higher-bandwidth connection can transfer more bits per second than a lower-bandwidth connection, all else being equal.","options":["True","False"],"answer":0,"explanation":"Bandwidth is a capacity measure, although real performance depends on other factors too.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-18","topic":"1.3","type":"multi","difficulty":"stretch","question":"Which factors can influence the experience of streaming video across a network?","options":["Available bandwidth","Number of competing users","Type and quality of media","Colour of the router's plastic case"],"answer":[0,1,2],"explanation":"Throughput and demand matter for video streaming.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-19","topic":"1.3","type":"mcq","difficulty":"secure","question":"Which combination is commonly found in a home networking hub?","options":["Router, switch and wireless access point","CPU, ALU and cache","Scanner, plotter and speaker","Compiler, interpreter and debugger"],"answer":0,"explanation":"Consumer equipment often combines routing, wired switching and Wi-Fi access.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-3-20","topic":"1.3","type":"mcq","difficulty":"secure","question":"How does Bluetooth usually differ from Wi-Fi?","options":["It is usually designed for short-range low-power connections","It can never communicate without the internet","It always offers a longer range than Wi-Fi","It uses DNS to pair devices"],"answer":0,"explanation":"Bluetooth is often used for short-range peripherals.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-01","topic":"1.4","type":"multi","difficulty":"core","question":"Which items are types of malware?","options":["Rootkit","Keylogger","NAT router","Sandboxing"],"answer":[0,1],"explanation":"Rootkits and keyloggers can be malicious software; NAT and sandboxing are not malware types.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-02","topic":"1.4","type":"mcq","difficulty":"core","question":"What is phishing?","options":["Tricking a user through a deceptive message or website","Trying every password automatically","Flooding a server with traffic","Copying a programme's source code"],"answer":0,"explanation":"Phishing uses fraudulent messages to obtain information or actions.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-03","topic":"1.4","type":"mcq","difficulty":"secure","question":"What does a brute-force attack attempt?","options":["Many possible passwords or keys until one works","Only one carefully guessed password","Only physically breaking a computer","Only intercepting a fibre-optic cable"],"answer":0,"explanation":"Brute force systematically tries multiple possibilities.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-04","topic":"1.4","type":"multi","difficulty":"core","question":"Which characteristics can make a password stronger?","options":["Greater length","Unpredictability","Unique use for each account","Using a pet's name and birth year"],"answer":[0,1,2],"explanation":"Long, unpredictable, unique passwords reduce guessing and reuse attacks.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-05","topic":"1.4","type":"mcq","difficulty":"secure","question":"What is social engineering?","options":["Manipulating people to bypass security procedures","A method for drawing algorithms","A way to encrypt a USB stick","A network cable connector"],"answer":0,"explanation":"Social engineering targets people's decisions rather than relying only on a technical vulnerability.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-06","topic":"1.4","type":"mcq","difficulty":"secure","question":"What is shoulder surfing?","options":["Watching someone enter private information","Sending fake technical-support emails","Overloading a website with requests","Encrypting a stolen database"],"answer":0,"explanation":"An attacker observes passwords or other information as they are entered.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-07","topic":"1.4","type":"mcq","difficulty":"secure","question":"What is a denial-of-service attack intended to do?","options":["Make a service unavailable to its users","Back up files safely","Increase network throughput","Improve server availability"],"answer":0,"explanation":"A DoS attack disrupts availability, often by overwhelming resources.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-08","topic":"1.4","type":"multi","difficulty":"secure","question":"Which measures help protect against malware?","options":["Updated anti-malware software","Software updates","Checking downloads and attachments","Opening any unknown attachment"],"answer":[0,1,2],"explanation":"Protection combines technical tools and safe user behaviour.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-09","topic":"1.4","type":"mcq","difficulty":"core","question":"What is a firewall primarily used for?","options":["Filtering network traffic against security rules","Cooling the CPU","Converting plaintext into a Caesar cipher","Defragmenting a storage drive"],"answer":0,"explanation":"A firewall allows or blocks traffic based on rules.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-10","topic":"1.4","type":"mcq","difficulty":"secure","question":"What is an SQL injection attack?","options":["Putting malicious database instructions into unsafely handled input","Intercepting radio signals with a larger antenna","Guessing a user's password from their birthday","Physically stealing a server"],"answer":0,"explanation":"Unsafe handling of input can let an attacker interfere with database queries.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-11","topic":"1.4","type":"multi","difficulty":"secure","question":"Which approaches help prevent SQL injection?","options":["Parameterized queries","Validating and handling inputs appropriately","Restricting database privileges","Building database queries by directly joining untrusted text"],"answer":[0,1,2],"explanation":"Parameterized queries and least privilege are important protections.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-12","topic":"1.4","type":"mcq","difficulty":"secure","question":"What is penetration testing?","options":["Authorised attempts to find and demonstrate security weaknesses","An attack that always steals data","Automatic replacement for all firewalls","A way to compress a network packet"],"answer":0,"explanation":"Penetration testers assess vulnerabilities with permission.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-13","topic":"1.4","type":"mcq","difficulty":"secure","question":"What is intrusion detection?","options":["Monitoring for evidence of suspicious or unauthorised activity","Physically locking every room","Writing backup copies to tape","Preventing all future attacks with certainty"],"answer":0,"explanation":"Intrusion detection helps spot suspicious activity, but does not guarantee prevention.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-14","topic":"1.4","type":"mcq","difficulty":"secure","question":"What is the principle of least privilege?","options":["Giving users only the permissions needed for their tasks","Giving every user administrator rights","Disabling all user accounts","Sharing one password across a department"],"answer":0,"explanation":"Limited permissions reduce damage when accounts are misused.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-15","topic":"1.4","type":"multi","difficulty":"core","question":"Which are physical network security controls?","options":["Door locks","CCTV","Security guards","A Python variable"],"answer":[0,1,2],"explanation":"Physical controls restrict access to equipment and facilities.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-16","topic":"1.4","type":"tf","difficulty":"core","question":"Encryption can reduce the risk of somebody reading sensitive information if they intercept it.","options":["True","False"],"answer":0,"explanation":"Encrypted data requires the appropriate key for decryption.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-17","topic":"1.4","type":"mcq","difficulty":"stretch","question":"Which is the clearest distinction between vulnerability scanning and intrusion detection?","options":["Scanning looks for weaknesses; detection looks for suspicious activity","Both do exactly the same job","Scanning is only physical; detection only applies to RAM","Intrusion detection always encrypts messages"],"answer":0,"explanation":"The former identifies weaknesses; the latter monitors activity.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-4-18","topic":"1.4","type":"mcq","difficulty":"secure","question":"Which is an example of multi-factor authentication?","options":["Password plus an authenticator-app code","Two different passwords of the same type","Username plus a full name","A password entered twice"],"answer":0,"explanation":"Multi-factor combines independent factor types, such as knowledge and possession.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-01","topic":"1.5","type":"mcq","difficulty":"core","question":"What is the main job of an operating system?","options":["Manage hardware and provide services to applications","Design a computer's circuit board","Write every user document automatically","Only connect a keyboard"],"answer":0,"explanation":"The OS manages resources and provides a platform for applications.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-02","topic":"1.5","type":"mcq","difficulty":"core","question":"What is a user interface?","options":["The means by which a user interacts with a system","A type of magnetic storage","A single program instruction","The speed of a network connection"],"answer":0,"explanation":"Interfaces can be graphical, command-line or other forms.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-03","topic":"1.5","type":"mcq","difficulty":"core","question":"Which is an example of a graphical user interface element?","options":["An icon that launches an application","A CPU register","An Ethernet frame","A hexadecimal address"],"answer":0,"explanation":"GUIs use graphical objects such as windows, icons, menus and pointers.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-04","topic":"1.5","type":"mcq","difficulty":"core","question":"How does a command-line interface normally accept instructions?","options":["The user types text commands","The user must use a touchscreen","The computer guesses user intentions","The user draws logic gates"],"answer":0,"explanation":"CLIs accept textual commands.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-05","topic":"1.5","type":"mcq","difficulty":"secure","question":"What does multitasking mean in an operating system?","options":["Managing the execution of more than one task","Running only one instruction in total","Using two different monitors","Keeping all files on two USB drives"],"answer":0,"explanation":"A multitasking OS shares processing time and manages concurrent tasks.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-06","topic":"1.5","type":"mcq","difficulty":"secure","question":"What does memory management handle?","options":["Allocating and releasing memory for programs","Ensuring that cables are the correct colour","Installing a mouse pad","Encoding a Caesar cipher"],"answer":0,"explanation":"The OS allocates memory and tracks memory use.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-07","topic":"1.5","type":"mcq","difficulty":"core","question":"Why is a device driver needed?","options":["To allow the OS to communicate with a particular hardware device","To increase the number of CPU cores","To change every file into a PDF","To make a network wireless"],"answer":0,"explanation":"Drivers are software interfaces between the operating system and devices.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-08","topic":"1.5","type":"mcq","difficulty":"core","question":"What is file management?","options":["Organising, naming, moving and accessing files","Only displaying video","Only removing malware","Physically rearranging CPU pins"],"answer":0,"explanation":"File management includes folders, files and permissions.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-09","topic":"1.5","type":"mcq","difficulty":"secure","question":"What is user management in a multi-user system?","options":["Creating accounts and controlling access rights","Defragmenting magnetic storage","Converting numbers into binary","Changing the computer's case"],"answer":0,"explanation":"User management controls identities and permissions.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-10","topic":"1.5","type":"mcq","difficulty":"core","question":"What does encryption do?","options":["Transforms readable data into a form that needs a key to read","Removes every computer virus","Speeds up all network transfers","Permanently deletes data"],"answer":0,"explanation":"Encryption protects confidentiality of information.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-11","topic":"1.5","type":"mcq","difficulty":"secure","question":"What is the purpose of data compression?","options":["Reducing the number of bits needed to represent data","Increasing file size to avoid losses","Always changing an image into text","Removing the need for backups"],"answer":0,"explanation":"Compression represents data using fewer bits.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-12","topic":"1.5","type":"mcq","difficulty":"secure","question":"What is disk defragmentation intended to improve on a traditional HDD?","options":["The arrangement of fragmented file data","Password strength","The number of CPU registers","The file's copyright status"],"answer":0,"explanation":"Traditional HDDs can benefit from reorganising scattered blocks; SSDs should not be routinely defragmented like HDDs.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-13","topic":"1.5","type":"mcq","difficulty":"secure","question":"What is a potential disadvantage of encrypting large amounts of data?","options":["Additional processing work for encryption and decryption","Guaranteed loss of all data","Faster transfer in every situation","It stops computers connecting to networks"],"answer":0,"explanation":"Cryptography requires processing, although modern hardware often accelerates it.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-14","topic":"1.5","type":"tf","difficulty":"core","question":"A graphical interface can use windows, icons, menus and a pointer.","options":["True","False"],"answer":0,"explanation":"These are common GUI elements.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-15","topic":"1.5","type":"mcq","difficulty":"secure","question":"What is the difference between utility software and general application software?","options":["Utilities maintain or protect the system; applications support user tasks","Applications must always be free; utilities must be paid","Only applications can run on Windows","Utility software is always stored in ROM"],"answer":0,"explanation":"Utilities focus on system maintenance and protection.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-5-16","topic":"1.5","type":"mcq","difficulty":"secure","question":"What is a common benefit of using a CLI for repeated administration?","options":["Commands can be scripted and automated","It prevents all user mistakes","It has no learning curve","It requires a mouse for every action"],"answer":0,"explanation":"Repeatable typed commands are useful for automation.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-01","topic":"1.6","type":"mcq","difficulty":"core","question":"What is an ethical issue?","options":["A question of what is right or wrong","A device hardware fault","The speed of a file transfer","A particular programming language"],"answer":0,"explanation":"Ethics involves judgements about right and wrong actions.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-02","topic":"1.6","type":"mcq","difficulty":"core","question":"What does digital divide refer to?","options":["Differences in access to and use of digital technology","The difference between binary 0 and 1","A split in an Ethernet cable","Two versions of a software licence"],"answer":0,"explanation":"People may lack devices, connectivity, skills or affordable access.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-03","topic":"1.6","type":"mcq","difficulty":"core","question":"What is internet trolling?","options":["Posting to provoke, upset or disrupt others online","Using a password manager","Sending a legitimate update reminder","Backing up a database"],"answer":0,"explanation":"Trolling deliberately provokes or disrupts online discussions.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-04","topic":"1.6","type":"multi","difficulty":"core","question":"Which health issues may be associated with poorly managed computer use?","options":["Repetitive strain injury","Eye strain","Poor posture and back pain","Guaranteed improved eyesight"],"answer":[0,1,2],"explanation":"Frequent breaks and appropriate equipment can reduce risks.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-05","topic":"1.6","type":"mcq","difficulty":"secure","question":"Which question is an ethical concern about self-driving vehicles?","options":["How responsibility is assigned after a collision","Whether a router uses DNS","Whether a hard disk is fragmented","Whether RAM is volatile"],"answer":0,"explanation":"Automated decisions can raise questions about safety and accountability.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-06","topic":"1.6","type":"mcq","difficulty":"secure","question":"How can AI support medical professionals?","options":["Helping analyse medical images and detect patterns","Replacing informed human review in every case","Guaranteeing diagnoses can never be wrong","Removing all patient privacy responsibilities"],"answer":0,"explanation":"AI can assist clinical work but has limitations and needs oversight.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-07","topic":"1.6","type":"mcq","difficulty":"core","question":"What is internet censorship?","options":["Limiting or blocking access to certain online material","Encrypting messages with a key","Moving files between folders","Sending email using SMTP"],"answer":0,"explanation":"Censorship restricts access to or publication of information.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-08","topic":"1.6","type":"mcq","difficulty":"secure","question":"What is e-waste?","options":["Discarded electrical and electronic equipment","Unused space in a file","Temporary data in cache","The amount of bandwidth lost"],"answer":0,"explanation":"Electronic waste needs responsible handling.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-09","topic":"1.6","type":"multi","difficulty":"secure","question":"Which are ways to reduce the impact of e-waste?","options":["Repairing devices","Reusing or donating working equipment","Approved recycling and safe disposal","Putting batteries into ordinary rubbish"],"answer":[0,1,2],"explanation":"Reuse and responsible recycling reduce materials waste and contamination.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-10","topic":"1.6","type":"mcq","difficulty":"secure","question":"Which issue can arise from automation in the workplace?","options":["Some roles may change or be lost as tasks are automated","All employees automatically receive a promotion","All organisations stop using electricity","Network security becomes unnecessary"],"answer":0,"explanation":"Automation can increase efficiency while affecting employment and skills.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-11","topic":"1.6","type":"mcq","difficulty":"core","question":"Which UK law concerns unauthorised access to computer systems?","options":["Computer Misuse Act 1990","Copyright, Designs and Patents Act 1988","Equality Act 2010","Sale of Goods Act 1979"],"answer":0,"explanation":"The Computer Misuse Act addresses unauthorised computer access and related offences.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-12","topic":"1.6","type":"mcq","difficulty":"core","question":"Which UK legislation is central to protecting original creative works?","options":["Copyright, Designs and Patents Act 1988","Computer Misuse Act 1990","Road Traffic Act 1988","Trade Descriptions Act 1968"],"answer":0,"explanation":"Copyright law protects qualifying original works. The source resource also discusses this Act.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-13","topic":"1.6","type":"mcq","difficulty":"secure","question":"What is personal data?","options":["Information relating to an identified or identifiable living person","Any number written in hexadecimal","Only information stored on paper","Only information freely published online"],"answer":0,"explanation":"Personal data includes information that can identify someone directly or indirectly.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-14","topic":"1.6","type":"mcq","difficulty":"secure","question":"What does the principle of data minimisation mean?","options":["Collect only personal data needed for the stated purpose","Keep everything forever just in case","Share all data with anyone who asks","Collect no data even when necessary"],"answer":0,"explanation":"Organisations should limit collection to what is necessary.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-15","topic":"1.6","type":"mcq","difficulty":"secure","question":"What is proprietary software?","options":["Software controlled under a licence with restrictions on use and source code","Software with no copyright rules at all","Software that cannot run on a desktop","Software whose source code must always be public"],"answer":0,"explanation":"Proprietary software has licence terms controlled by its owner.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-16","topic":"1.6","type":"mcq","difficulty":"secure","question":"What is open-source software?","options":["Software distributed with a licence allowing access to and modification of its source code","Software that is always free of all conditions","Software that can never contain errors","Software that cannot be sold"],"answer":0,"explanation":"Open-source licences permit study, modification and redistribution under their terms.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-17","topic":"1.6","type":"tf","difficulty":"core","question":"Someone who buys a music recording automatically gains the copyright to redistribute it without restriction.","options":["True","False"],"answer":1,"explanation":"Buying a recording does not transfer copyright or unlimited distribution rights.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"1-6-18","topic":"1.6","type":"mcq","difficulty":"secure","question":"Which is a likely environmental impact of increasing digital-device use?","options":["Energy consumption and extraction of materials","Computers no longer needing electricity","All e-waste being biodegradable","Infinite supplies of rare metals"],"answer":0,"explanation":"Manufacturing, powering and disposing of devices affect the environment.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-01","topic":"2.1","type":"mcq","difficulty":"core","question":"What is decomposition?","options":["Breaking a complex problem into smaller, manageable parts","Removing all detail from a model","Repeating an instruction a fixed number of times","Sorting items into reverse order"],"answer":0,"explanation":"Decomposition makes complex problems easier to understand and solve.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-02","topic":"2.1","type":"mcq","difficulty":"core","question":"What is abstraction?","options":["Ignoring irrelevant detail and focusing on essentials","Breaking every program into one line","Guessing the answer without a model","Writing the final program without testing"],"answer":0,"explanation":"Abstraction identifies the important information for a particular purpose.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-03","topic":"2.1","type":"mcq","difficulty":"core","question":"What must be true of data before using a standard binary search?","options":["It must be sorted into a consistent order","It must contain only integers","It must be stored on a server","It must have exactly ten items"],"answer":0,"explanation":"Binary search depends on ordering to choose half of the remaining items.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-04","topic":"2.1","type":"mcq","difficulty":"secure","question":"What happens first in a binary search?","options":["Inspect the middle item of the sorted search range","Compare all items simultaneously","Shuffle the list at random","Start at the final item and inspect all items"],"answer":0,"explanation":"Binary search compares the target with the middle item.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-05","topic":"2.1","type":"mcq","difficulty":"secure","question":"How does a linear search operate?","options":["Check items one by one until found or the list is exhausted","Always choose the middle item","Require the list to be sorted","Swap adjacent items until ordered"],"answer":0,"explanation":"Linear search checks each element in sequence.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-06","topic":"2.1","type":"mcq","difficulty":"secure","question":"Why might binary search be preferred to linear search for a large sorted list?","options":["It repeatedly halves the search space","It never uses comparisons","It automatically encrypts the list","It can only search lists of ten items"],"answer":0,"explanation":"Binary search needs far fewer comparisons on large sorted data.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-07","topic":"2.1","type":"mcq","difficulty":"core","question":"What data type stores True or False?","options":["Boolean","Integer","String","Real"],"answer":0,"explanation":"Boolean variables have two logical states.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-08","topic":"2.1","type":"mcq","difficulty":"secure","question":"What does bubble sort do?","options":["Repeatedly compares neighbouring items and swaps them if out of order","Always selects the middle item of a sorted list","Randomises all elements until sorted","Uses the largest value as a hash key"],"answer":0,"explanation":"Bubble sort swaps adjacent out-of-order items over multiple passes.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-09","topic":"2.1","type":"mcq","difficulty":"secure","question":"Why might bubble sort use a Boolean variable called swapped?","options":["To detect whether any exchange happened during a pass","To store the first name alphabetically","To count CPU cores","To reverse all comparisons"],"answer":0,"explanation":"If a complete pass makes no swaps, the list is already sorted.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-10","topic":"2.1","type":"mcq","difficulty":"secure","question":"What is needed to swap two stored values safely?","options":["A temporary variable or equivalent tuple assignment","Only assigning A = B","Only deleting B","A file compression utility"],"answer":0,"explanation":"Without temporary storage, the first value can be overwritten.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-11","topic":"2.1","type":"mcq","difficulty":"secure","question":"What is an algorithm?","options":["A finite set of precise steps to solve a problem","Any computer hardware device","An encrypted file format","A type of network cable"],"answer":0,"explanation":"Algorithms describe processes independent of a particular language.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-12","topic":"2.1","type":"mcq","difficulty":"core","question":"Which flowchart shape normally represents a decision?","options":["Diamond","Rectangle","Oval","Parallelogram"],"answer":0,"explanation":"Decision nodes branch on a condition, such as yes/no.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-13","topic":"2.1","type":"mcq","difficulty":"core","question":"Which shape commonly represents input or output in a flowchart?","options":["Parallelogram","Diamond","Circle","Hexagon"],"answer":0,"explanation":"Input/output is usually shown with a parallelogram.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-14","topic":"2.1","type":"mcq","difficulty":"secure","question":"What is a trace table used for?","options":["Tracking variable values as an algorithm executes","Measuring cable length","Encrypting a database","Measuring screen refresh rate"],"answer":0,"explanation":"Trace tables help predict outputs and locate errors.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-15","topic":"2.1","type":"tf","difficulty":"secure","question":"Binary search can always be used correctly on a completely unsorted list.","options":["True","False"],"answer":1,"explanation":"The standard algorithm requires sorted data.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-16","topic":"2.1","type":"mcq","difficulty":"stretch","question":"What is the worst-case time complexity of a basic linear search?","options":["O(n)","O(log n)","O(1) for every input","O(n²) for every input"],"answer":0,"explanation":"In the worst case a linear search examines all n items.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-1-17","topic":"2.1","type":"mcq","difficulty":"stretch","question":"What is the worst-case time complexity of binary search on a sorted array?","options":["O(log n)","O(n²)","O(n!)","O(n) for every input"],"answer":0,"explanation":"Halving the range yields logarithmic growth.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-01","topic":"2.2","type":"mcq","difficulty":"core","question":"How does a constant differ from a variable?","options":["Its stored value should not change while the program runs","It can only hold text","It must be stored in ROM","It cannot have an identifier"],"answer":0,"explanation":"Both hold values, but a constant is intended not to change.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-02","topic":"2.2","type":"mcq","difficulty":"core","question":"What does an assignment statement do?","options":["Stores a new value in a variable","Checks whether two values are equal","Stops a loop permanently","Creates a new input device"],"answer":0,"explanation":"Assignment updates the value associated with an identifier.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-03","topic":"2.2","type":"mcq","difficulty":"core","question":"What is selection in programming?","options":["Choosing which instructions run based on a condition","Repeating code a fixed number of times","Running statements only in order without choices","Adding adjacent numbers"],"answer":0,"explanation":"IF/ELSE is an example of selection.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-04","topic":"2.2","type":"mcq","difficulty":"core","question":"What is iteration?","options":["Repeating instructions with a loop","Checking a single condition once","Defining a constant","Only assigning a string"],"answer":0,"explanation":"FOR, WHILE and REPEAT constructs perform iteration.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-05","topic":"2.2","type":"mcq","difficulty":"secure","question":"What does MOD calculate?","options":["The remainder after integer division","The quotient including decimals","A number's square root","Its absolute value"],"answer":0,"explanation":"17 MOD 5 is 2 because 17 = 3×5 + 2.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-06","topic":"2.2","type":"trace","difficulty":"core","question":"Evaluate 23 MOD 5.","options":["3","4","5","2"],"answer":0,"explanation":"5 fits into 23 four times with remainder 3.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-07","topic":"2.2","type":"trace","difficulty":"core","question":"Evaluate 19 DIV 4, where DIV is integer division.","options":["4","3","4.75","5"],"answer":0,"explanation":"DIV gives the whole-number quotient: 19 DIV 4 = 4.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-08","topic":"2.2","type":"trace","difficulty":"secure","question":"What is the value of x after: x = 8; x = x + 5?","options":["13","8","5","40"],"answer":0,"explanation":"The second assignment replaces x with 8 + 5.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-09","topic":"2.2","type":"trace","difficulty":"secure","question":"A condition is: IF score >= 50 THEN PASS. What happens when score is 50?","options":["The PASS branch runs","The PASS branch does not run","The program must crash","The value is rounded to 49"],"answer":0,"explanation":">= includes the boundary value 50.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-10","topic":"2.2","type":"mcq","difficulty":"core","question":"What data type is most suitable for the number of pupils in a classroom?","options":["Integer","Boolean","Character","Real"],"answer":0,"explanation":"Counting whole people requires whole numbers.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-11","topic":"2.2","type":"mcq","difficulty":"core","question":"Which data type would normally store a single letter?","options":["Character","Integer","Boolean","Real"],"answer":0,"explanation":"A character holds one symbol.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-12","topic":"2.2","type":"mcq","difficulty":"core","question":"Which data type would normally store a person's full name?","options":["String","Integer","Boolean","Real"],"answer":0,"explanation":"Strings represent sequences of characters.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-13","topic":"2.2","type":"mcq","difficulty":"secure","question":"What is the purpose of a subprogram?","options":["To group reusable instructions into a named routine","To disable all input validation","To force every variable to be global","To remove the need for algorithms"],"answer":0,"explanation":"Procedures and functions support modular programming.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-14","topic":"2.2","type":"mcq","difficulty":"secure","question":"What is a parameter?","options":["A value or identifier passed into a subprogram","A variable that can never change","The final line of the program","A type of syntax error"],"answer":0,"explanation":"Parameters let routines operate on supplied information.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-15","topic":"2.2","type":"mcq","difficulty":"secure","question":"What is an array?","options":["A collection of values accessed by an index","A command to clear the screen","A form of malware","A logical operator"],"answer":0,"explanation":"Arrays store indexed elements.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-16","topic":"2.2","type":"mcq","difficulty":"secure","question":"How can random selection support a game?","options":["Select different outcomes within a defined range","Guarantee the same result every run","Replace every programming construct","Prevent any possibility of a bug"],"answer":0,"explanation":"A random number can choose among game actions.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-17","topic":"2.2","type":"trace","difficulty":"stretch","question":"What is 3 + 4 * 2 with normal operator precedence?","options":["11","14","10","16"],"answer":0,"explanation":"Multiplication occurs before addition.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-18","topic":"2.2","type":"trace","difficulty":"stretch","question":"Evaluate (27 MOD 8) + (18 DIV 5).","options":["6","7","8","9"],"answer":0,"explanation":"27 MOD 8 = 3 and 18 DIV 5 = 3, giving 6.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-19","topic":"2.2","type":"mcq","difficulty":"secure","question":"Why is input conversion sometimes needed before arithmetic?","options":["Input may be received as text rather than a number","Every number is automatically Boolean","It makes the CPU run without RAM","It changes multiplication into division"],"answer":0,"explanation":"Numeric operations need appropriate numeric data types.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-2-20","topic":"2.2","type":"tf","difficulty":"core","question":"A WHILE loop normally checks a condition to decide whether to continue.","options":["True","False"],"answer":0,"explanation":"While loops are condition-controlled.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-01","topic":"2.3.1","type":"mcq","difficulty":"core","question":"What is a code comment?","options":["Text for programmers that is not executed as an instruction","An instruction to format a drive","A line that must always print on screen","A command to delete variables"],"answer":0,"explanation":"Comments document the intention of code.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-02","topic":"2.3.1","type":"mcq","difficulty":"core","question":"Why are meaningful variable names useful?","options":["They make code easier to understand and maintain","They guarantee perfect performance","They prevent all unauthorised access","They remove the need for testing"],"answer":0,"explanation":"Clear identifiers explain the role of stored values.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-03","topic":"2.3.1","type":"mcq","difficulty":"core","question":"What is indentation in code?","options":["Using consistent spacing to show nested blocks","Changing the colour of a monitor","Sorting text in alphabetical order","Encrypting a program"],"answer":0,"explanation":"Indentation makes program structure visible.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-04","topic":"2.3.1","type":"mcq","difficulty":"secure","question":"How do subprograms improve maintainability?","options":["They isolate reusable tasks into manageable sections","They prevent every runtime error","They make all programs the same length","They prevent changes to a program"],"answer":0,"explanation":"Modular code can be reused and changed more easily.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-05","topic":"2.3.1","type":"mcq","difficulty":"secure","question":"What does validation do?","options":["Checks whether input meets specified rules","Confirms that input is true in the real world","Encrypts all input automatically","Erases all invalid files"],"answer":0,"explanation":"Validation tests format, type, range or presence, not whether real-world details are necessarily accurate.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-06","topic":"2.3.1","type":"mcq","difficulty":"core","question":"Which is a range check?","options":["Age must be from 11 to 18","Email must contain an @ sign","The field must not be empty","Password must use a particular file extension"],"answer":0,"explanation":"A range check requires a value to fall between limits.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-07","topic":"2.3.1","type":"mcq","difficulty":"core","question":"Which is a presence check?","options":["Requiring a field to contain a value","Requiring a value below 100","Requiring eight characters exactly","Checking letters against a pattern"],"answer":0,"explanation":"Presence checks reject blank required fields.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-08","topic":"2.3.1","type":"mcq","difficulty":"core","question":"Which is a length check?","options":["A password must contain at least 12 characters","A score must be between 0 and 10","An email must include a dot","A record must be backed up"],"answer":0,"explanation":"Length checks test the number of characters.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-09","topic":"2.3.1","type":"mcq","difficulty":"secure","question":"What does authentication establish?","options":["Whether a user is who they claim to be","Whether a number is within range","Whether a file is compressed","Whether a screen is calibrated"],"answer":0,"explanation":"Authentication checks a claimed identity.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-10","topic":"2.3.1","type":"mcq","difficulty":"secure","question":"Why might a login page use CAPTCHA?","options":["To reduce automated submissions by bots","To ensure passwords are never stolen","To calculate a user's age","To replace all security controls"],"answer":0,"explanation":"CAPTCHA aims to distinguish human interaction from automated abuse.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-11","topic":"2.3.1","type":"mcq","difficulty":"secure","question":"What is a robust way of restricting unauthorised functions?","options":["Access controls with role-appropriate permissions","Giving everyone one shared administrator account","Accepting any username","Disabling all password checks"],"answer":0,"explanation":"Authorisation controls what authenticated users can do.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-12","topic":"2.3.1","type":"mcq","difficulty":"secure","question":"What is defensive design?","options":["Designing systems to cope with misuse and incorrect input","Only making code look attractive","Running tests once after release","Compressing source code into a zip"],"answer":0,"explanation":"Defensive design anticipates unwanted or invalid behaviour.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-13","topic":"2.3.1","type":"mcq","difficulty":"secure","question":"What is sanitising input?","options":["Treating or cleaning untrusted input so it is handled safely","Automatically deleting all user accounts","Encrypting every message with Caesar","Increasing input length"],"answer":0,"explanation":"Safe input handling helps protect a system, especially when combined with appropriate APIs.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-14","topic":"2.3.1","type":"tf","difficulty":"core","question":"Indentation and code comments can help other programmers understand a program.","options":["True","False"],"answer":0,"explanation":"Both improve readability and maintainability.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-1-15","topic":"2.3.1","type":"tf","difficulty":"secure","question":"If an input passes validation, it must be factually true.","options":["True","False"],"answer":1,"explanation":"A correctly formatted date or email can still be false.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-01","topic":"2.3.2","type":"mcq","difficulty":"core","question":"Why is software tested?","options":["To discover errors and check whether requirements are met","To remove every line of source code","To guarantee no bug can ever occur","To avoid documenting decisions"],"answer":0,"explanation":"Testing checks behaviour and reveals defects.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-02","topic":"2.3.2","type":"mcq","difficulty":"core","question":"What is a syntax error?","options":["Code that breaks the language's grammar rules","A program that produces a wrong result despite running","A poorly chosen font colour","An outdated website"],"answer":0,"explanation":"Syntax errors prevent a program from being correctly parsed.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-03","topic":"2.3.2","type":"mcq","difficulty":"core","question":"What is a logic error?","options":["A valid program that produces incorrect behaviour","An incorrectly spelt keyword that cannot parse","A damaged keyboard","An entirely missing power supply"],"answer":0,"explanation":"Logic errors may allow execution but give wrong outputs.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-04","topic":"2.3.2","type":"mcq","difficulty":"core","question":"What is normal test data?","options":["Typical valid values that should be accepted","Only values outside the permitted range","Only missing values","Only malicious network packets"],"answer":0,"explanation":"Normal data represents expected inputs.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-05","topic":"2.3.2","type":"mcq","difficulty":"core","question":"What is boundary test data?","options":["Values at or close to allowed limits","Only letters from the alphabet","Only values that are always accepted","Only empty strings"],"answer":0,"explanation":"Boundary tests focus on edge cases.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-06","topic":"2.3.2","type":"mcq","difficulty":"core","question":"What is invalid test data?","options":["Values that should be rejected by validation","Typical acceptable data","Only minimum valid values","All values that contain a digit"],"answer":0,"explanation":"Invalid data deliberately violates requirements.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-07","topic":"2.3.2","type":"mcq","difficulty":"secure","question":"A valid score range is 0 to 100 inclusive. Which is a useful boundary test?","options":["100","50","75","62"],"answer":0,"explanation":"100 is a permitted boundary; 101 would test just outside it.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-08","topic":"2.3.2","type":"mcq","difficulty":"secure","question":"For an age field allowing 9 to 15 inclusive, which should be rejected?","options":["16","9","12","15"],"answer":0,"explanation":"16 lies outside the upper boundary.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-09","topic":"2.3.2","type":"mcq","difficulty":"secure","question":"What is iterative testing?","options":["Testing and improving a program repeatedly during development","Testing only after a product is released","Checking only the user guide","Never retesting after fixes"],"answer":0,"explanation":"Regular testing lets developers correct problems as they build.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-10","topic":"2.3.2","type":"mcq","difficulty":"secure","question":"What is final testing?","options":["Checking the completed product against requirements before release","Testing before any code exists","Only measuring CPU temperature","Replacing validation with encryption"],"answer":0,"explanation":"Final testing verifies the finished product.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-11","topic":"2.3.2","type":"mcq","difficulty":"secure","question":"A program uses 'score == 4' when it intends to assign the value 4. What is the likely mistake?","options":["Comparison was used instead of assignment","The variable has too many characters","The score is automatically encrypted","The result must always be 4"],"answer":0,"explanation":"Equality comparison and assignment are different operations.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-12","topic":"2.3.2","type":"mcq","difficulty":"secure","question":"A football app uses a correct size for teenagers but assigns the wrong weight. What type of error is this?","options":["Logic error","Operating-system failure","Physical network fault","Data compression error"],"answer":0,"explanation":"The program runs but some results are incorrect.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-13","topic":"2.3.2","type":"mcq","difficulty":"secure","question":"Why should a fixed defect be retested?","options":["A correction may introduce other unexpected behaviour","It guarantees a higher screen resolution","To delete all test evidence","So the original requirements can be ignored"],"answer":0,"explanation":"Regression testing checks that existing features still work.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-14","topic":"2.3.2","type":"multi","difficulty":"secure","question":"Which would form a sensible test set for an allowed number range 1 to 10?","options":["1","10","0","11"],"answer":[0,1,2,3],"explanation":"Useful tests include both boundaries and values just outside them.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-3-2-15","topic":"2.3.2","type":"tf","difficulty":"core","question":"Testing can prove with certainty that any non-trivial program contains no bugs.","options":["True","False"],"answer":1,"explanation":"Testing finds defects, but exhaustive proof from tests alone is generally impossible.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-01","topic":"2.4","type":"mcq","difficulty":"core","question":"Why do digital computers use binary?","options":["Electronic circuits can represent two distinct states","Computers cannot store any other number","Decimal arithmetic is illegal","Text cannot be encoded in binary"],"answer":0,"explanation":"Switching circuits can represent off/on as 0/1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-02","topic":"2.4","type":"mcq","difficulty":"core","question":"Which component can act as an electronic switch inside computer circuits?","options":["Transistor","Printer","Loudspeaker","Hard disk platter"],"answer":0,"explanation":"Transistors form the basis of digital logic circuitry.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-03","topic":"2.4","type":"trace","difficulty":"core","question":"What does AND output for inputs A=1 and B=0?","options":["0","1","2","Undefined"],"answer":0,"explanation":"AND outputs 1 only when all inputs are 1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-04","topic":"2.4","type":"trace","difficulty":"core","question":"What does OR output for inputs A=1 and B=0?","options":["1","0","2","Undefined"],"answer":0,"explanation":"OR outputs 1 if at least one input is 1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-05","topic":"2.4","type":"trace","difficulty":"core","question":"What does NOT output for input A=0?","options":["1","0","2","Undefined"],"answer":0,"explanation":"NOT reverses a bit.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-06","topic":"2.4","type":"mcq","difficulty":"core","question":"Which Boolean expression represents the output of an AND gate?","options":["A AND B","A OR B","NOT A","A + B as normal arithmetic"],"answer":0,"explanation":"AND requires both inputs to be true.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-07","topic":"2.4","type":"mcq","difficulty":"core","question":"When does an OR gate output 0?","options":["When both inputs are 0","Whenever either input is 1","Only when both inputs are 1","Never"],"answer":0,"explanation":"OR outputs 0 only if no input is 1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-08","topic":"2.4","type":"trace","difficulty":"secure","question":"Evaluate (A AND B) OR C when A=1, B=0, C=1.","options":["1","0","2","Depends on the cable"],"answer":0,"explanation":"1 AND 0 = 0, then 0 OR 1 = 1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-09","topic":"2.4","type":"trace","difficulty":"secure","question":"Evaluate (A AND B) AND (NOT C) for A=1, B=1, C=0.","options":["1","0","2","Undefined"],"answer":0,"explanation":"AND(1,1)=1 and NOT 0=1, so final output is 1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-10","topic":"2.4","type":"trace","difficulty":"secure","question":"Evaluate (NOT A) AND B for A=0, B=1.","options":["1","0","2","Undefined"],"answer":0,"explanation":"NOT 0=1; 1 AND 1=1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-11","topic":"2.4","type":"trace","difficulty":"secure","question":"Evaluate (NOT A) OR B for A=1, B=0.","options":["0","1","2","Undefined"],"answer":0,"explanation":"NOT 1=0 and 0 OR 0=0.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-12","topic":"2.4","type":"mcq","difficulty":"secure","question":"What is a truth table?","options":["A table showing outputs for each combination of input bits","A list of every variable name in a program","A record of every file on a disk","A chart of data transfer rates"],"answer":0,"explanation":"Truth tables enumerate all possible combinations of logical inputs.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-13","topic":"2.4","type":"mcq","difficulty":"secure","question":"How many combinations of inputs are possible for three Boolean inputs?","options":["8","6","3","16"],"answer":0,"explanation":"Each input has two possibilities, giving 2³ = 8.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-14","topic":"2.4","type":"multi","difficulty":"secure","question":"Which expressions are true when A=1 and B=0?","options":["A OR B","NOT B","A AND B","NOT A"],"answer":[0,1],"explanation":"A OR B and NOT B are true for these values.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-15","topic":"2.4","type":"tf","difficulty":"core","question":"For two inputs, an AND gate and an OR gate give identical outputs for every input combination.","options":["True","False"],"answer":1,"explanation":"They differ when exactly one input is 1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-16","topic":"2.4","type":"trace","difficulty":"stretch","question":"Calculate Q = (NOT A) OR (B AND C) for A=1, B=1, C=0.","options":["0","1","2","Undefined"],"answer":0,"explanation":"NOT A=0 and B AND C=0, so Q=0.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-17","topic":"2.4","type":"trace","difficulty":"stretch","question":"Calculate Q = (A OR B) AND NOT C for A=0, B=1, C=0.","options":["1","0","2","Undefined"],"answer":0,"explanation":"A OR B=1; NOT C=1; 1 AND 1=1.","source":"Adapted from the supplied OCR end-of-topic quiz"},{"id":"2-4-18","topic":"2.4","type":"mcq","difficulty":"stretch","question":"For four independent Boolean inputs, how many rows are in a full truth table?","options":["16","8","4","32"],"answer":0,"explanation":"A truth table has 2ⁿ rows for n Boolean inputs.","source":"Adapted from the supplied OCR end-of-topic quiz"}];
